-- 341_seed_machine_translations_item11.sql  (v1.41.0, item 11)
--
-- Machine-translated proposal seeds (es/ru/uk/sv) for the three Info-library
-- articles item 11 re-keyed: 3 keys, 12 pairs. Same contract as
-- 184/189/213/223/239/243/249/256/265/289/303/313/318 — PENDING proposals
-- only, sentinel proposer 'claude-mt', license_assent TRUE at the
-- machine-translation terms revision.
--
-- The same 12 translations are owed to plugin/I18nCatalogues.cs, which is what
-- a player actually renders — with no approval and no server (#583). That file
-- belongs to the client lane and this branch does not change it, so until that
-- lane ships, a player renders the PREDECESSOR article from their own DLL and
-- these rows are the only place the corrected translations exist. They are
-- here so a human translator can see and refine them through the portal, where
-- an approval overrides the bundled value via the pack overlay.
--
-- ALL TWELVE ARE UNREVIEWED MACHINE OUTPUT, and none of them is a revision of
-- an earlier translation. There is nothing to revise: 340 runs first and
-- REFUSES (its section-2 guard) if any of the three PREDECESSOR keys carries
-- an approved entry, so at the moment these rows land no approved predecessor
-- text exists that could have been carried forward — and a pending
-- predecessor proposal is superseded by 340, never edited into one of these.
-- Whoever reviews these in the portal is reading a fresh machine translation
-- against the English, not checking a diff against something a human already
-- signed off. A header claiming the opposite would license exactly the
-- light-touch approval this paragraph exists to prevent.
--
-- The twelve strings the client lane needs are the ones below; the step that
-- carries them into the catalogue, and where to recover them from, is written
-- out for that lane in docs/faq-refresh-client-contract.md.
--
-- key_id = sha1("client" || chr(0) || source)[:16] — the NUL-separator form
-- tools/i18n_sync_keys.py uses.
--
-- ORDERING: seeds only keys already present in i18n_keys. Run order:
-- deploy API -> apply 340 (or run tools/i18n_sync_keys.py) -> apply this file.
-- On an unsynced database the assertion below RAISEs and the transaction rolls
-- back; re-run once the keys land. Explicit BEGIN/COMMIT (#340); every
-- statement is idempotent under the wrapper's || re-run (#243).

BEGIN;

CREATE TEMP TABLE _seed341 (
  key_id      VARCHAR(16) NOT NULL,
  lang        VARCHAR(8)  NOT NULL,
  source_hash VARCHAR(40) NOT NULL,
  target      TEXT        NOT NULL
) ON COMMIT DROP;

INSERT INTO _seed341 (key_id, lang, source_hash, target) VALUES
  -- ranked_1v1_article (fc07ba40fe031c27)
     ('fc07ba40fe031c27', 'es', '0aa41f4136b6fb6ac705d0f82fccc62a6fd86ca6', E'El ranked 1v1 es el modo central del mod: series al mejor de 3, un rating Glicko, y dos formas de empezar una serie clasificada - la cola, o una sala privada donde ambos jugadores usan el mod. Esta página cubre la cola de Buscar a sala, cómo una sala privada se vuelve clasificada, y exactamente qué hace una desconexión.\n\n<color=#FFD94D><b>ENCONTRAR RIVAL</b></color>\n\n- Hacer clic en Buscar es en sí el opt-in a ranked - entrar en la cola activa Ranked en tu cuenta.\n- Tu banda de búsqueda empieza en 100 de rating en cada dirección y se ensancha esperando: 200 tras 30 segundos, 400 tras 60, 800 tras 120. Nunca pasa de 800.\n- El solape es <color=#7FD4FF>bilateral</color>: debes estar dentro de la banda de tu rival Y él dentro de la tuya. Alguien que espera 2 minutos con banda ancha no puede atrapar a un recién llegado cuya banda estrecha lo excluye.\n- Entre candidatos válidos, gana el rating más cercano.\n- Los jugadores que rechazaste en los últimos 5 minutos, los que has bloqueado (en cualquier dirección) y las cuentas baneadas nunca se ofrecen.\n- Buscar mientras juegas casual está bien - el quickplay vanilla y las salas casual normales nunca cancelan tu búsqueda. Entrar en cualquier sala creada por el mod (un torneo, 2v2, 1v2 o FFA) la cancela al instante.\n- Tras 30 minutos de búsqueda se te retira de la cola. <color=#8A8A93>Reencola si sigues ahí - el cliente 1v1 nunca reencola por ti.</color>\n\n<color=#FFD94D><b>PONERSE LISTO, RECHAZAR Y LA SALA</b></color>\n\n- Al emparejarte recibes un cartel de EMPAREJADO con el nombre y rating de tu rival, un sonido y un parpadeo en la barra de tareas. Debes hacer clic en Listo - no hay auto-listo.\n- Tienes 90 segundos, y cuando cualquiera de los dos pulsa Listo la ventana se reinicia a 90 frescos para ambos - alguien lento con el alt-tab siempre tiene tiempo completo. Si se agota, ambos volvéis a buscar.\n- Rechazar os devuelve a ambos a la cola y os impide re-emparejaros durante 5 minutos. Con la sala ya emitida, rechazar deja de funcionar.\n- Cuando ambos están listos el servidor emite una sala ranked privada y elige la región Photon: si ambos clientes reportan la misma región de casa, esa gana; si no, cae en cascada por las regiones vivas de los jugadores, luego cualquiera de las de casa, luego US.\n- Tu cliente fija esa región antes de unirse, para que los dos aterricéis en una sala en vez de dos salas homónimas en dos continentes.\n- Si tu rival nunca llega: un aviso a los 15 segundos, y una vuelta automática al menú a los 60. <color=#7FE87F>Sin penalización para ninguno.</color>\n\n<color=#FFD94D><b>RANKED EN SALA PRIVADA</b></color>\n\n- Una partida por código se clasifica cuando tres cosas son ciertas: tu interruptor Ranked activo, tu rival con Ranked activado, y tu rival usando el mod. Un rival que nunca ha usado el mod no puede hacer clasificada una partida jamás. (Una excepción deliberada: una serie viva sin terminar de una sesión anterior conserva su estado ranked cuando os volvéis a ver.)\n- En cuanto ambos mods se ven, el cliente registra la serie con el servidor (el <color=#7FD4FF>preflight</color>) - así la serie existe, y es apostable, durante el juego 1.\n- Si cualquiera tiene Ranked desactivado, el servidor rechaza la serie y recibes un aviso: la partida se juega como casual. Las partidas casual también se registran - solo que nunca tocan rating.\n- Las salas de cola y torneo se saltan estas comprobaciones por completo: encolar fue el consentimiento.\n\n<color=#FFD94D><b>LA SERIE</b></color>\n\n- El primero en 2 juegos ganados se lleva la serie. <color=#7FE87F>El rating se mueve solo al completarse una serie</color> - la serie entera es un único resultado de rating, y los juegos individuales nunca mueven rating por sí solos.\n- Una serie sin decidir - al menos un juego jugado, nadie con 2 victorias - <color=#7FE87F>nunca caduca</color>. Juega con el mismo rival mañana o la semana que viene y el juego 1 sigue en pie; tu HUD retoma el marcador vigente en vez de reiniciar a 0-0.\n- Esa regla de no-caducidad es deliberada: una ventana de caducidad dejaba que un jugador 0-1 abandonara la serie y esperara al reloj para esquivar la derrota.\n- Una serie no de torneo donde nunca se terminó un juego se abandona a los 30 minutos; el siguiente encuentro empieza de cero. Las series de torneo esperan a su cuadro.\n- Las apuestas de una serie estancada 60 minutos se devuelven (series de torneo aparte) - la serie en sí sigue reanudable.\n- Durante la ronda 1 de cada juego, el cliente reporta puntos en vivo al servidor. Las apuestas se bloquean cuando se han anotado 2 puntos totales en el juego 1 (un 1-1 cuenta) - o en cuanto cualquier juego de la serie se decide.\n\n<color=#FFD94D><b>DESCONEXIONES</b></color>\n\nLo que hace una DC depende del marcador, y lo juzga el jugador que SE QUEDÓ:\n\n- Estabas a punto de partida (4 rondas) cuando tu rival cayó: ganas el juego con el marcador vigente.\n- 4-4: te llevas el juego, registrado 5-4.\n- En cualquier otro caso - incluido un rival que cae yendo POR DELANTE - el juego se cancela. Nadie gana, nadie pierde.\n- Dejar una partida para entrar en tu propio emparejamiento ranked en cola se anuncia por adelantado y nunca se te cuenta en contra.\n\nLas reglas anti-abuso:\n\n- Solo el jugador que se quedó en la sala y vio irse al otro puede reclamar una victoria por DC. <color=#7FE87F>El cliente de quien se va nunca puede premiarse nada a sí mismo.</color>\n- Si el rival reconecta antes de que salgas, la reclamación se descarta.\n- Si caen AMBOS jugadores, nadie se quedó a observar: sin victoria, sin marca de abandono. Con un juego completado en el marcador la serie sigue activa y se reanuda cuando volváis a veros.\n- <color=#FF6666>Un juego cancelado no borra la serie</color> - los juegos completados se mantienen, y la serie se reanuda como arriba.\n\n<color=#FFD94D><b>PORCENTAJE DE ABANDONO</b></color>\n\n- Una DC ranked con juego significativo detrás (2 o más puntos, o una ronda completada, en el juego ACTUAL), sin nadie a punto de partida, se registra como abandono contra quien se fue - como mucho uno por jugador por serie.\n- <color=#7FD4FF>% de abandono</color> = DCs ranked divididas por victorias + derrotas + DCs de series ranked. Bajo el 5 por ciento sale verde, de 5 a menos de 15 ámbar, 15 o más rojo - visible para todos en la clasificación.\n- Una DC a punto de partida se convierte en victoria por DC para el otro jugador, no en marca de abandono.\n\nPara el árbol de decisión completo de se-registra-o-no, ver <color=#7FD4FF>Cuándo cuenta una partida</color>.')
  ,  ('fc07ba40fe031c27', 'ru', '0aa41f4136b6fb6ac705d0f82fccc62a6fd86ca6', E'Рейтинговый 1v1 - главный режим мода: серии best-of-3, один рейтинг Glicko и два способа начать рейтинговую серию - очередь или приватная комната, где оба игрока на моде. Эта страница - очередь от Поиска до комнаты, как приватное лобби становится рейтинговым и что именно делает дисконнект.\n\n<color=#FFD94D><b>ПОИСК СОПЕРНИКА</b></color>\n\n- Клик по Поиску - и есть рейтинговое согласие: вход в очередь включает Ranked на твоём аккаунте.\n- Твой диапазон поиска начинается со 100 рейтинга в обе стороны и растёт с ожиданием: 200 после 30 секунд, 400 после 60, 800 после 120. Шире 800 он не растёт никогда.\n- Пересечение <color=#7FD4FF>двустороннее</color>: ты должен быть внутри диапазона соперника, И он внутри твоего. Двухминутный ожидающий с широким диапазоном не схватит свежего новичка, чей узкий диапазон его исключает.\n- Среди подходящих кандидатов побеждает ближайший рейтинг.\n- Игроки, которых ты отклонил за последние 5 минут, игроки в блоке (в любую сторону) и забаненные аккаунты не предлагаются никогда.\n- Искать, играя казуал, можно: ванильный quickplay и обычные казуальные комнаты твой поиск не отменяют. Вход в любую комнату мода (турнир, 2v2, 1v2 или FFA) отменяет его немедленно.\n- После 30 минут поиска тебя убирают из очереди. <color=#8A8A93>Встань снова, если ты ещё тут, - клиент 1v1 никогда не перевстаёт за тебя.</color>\n\n<color=#FFD94D><b>ГОТОВНОСТЬ, ОТКЛОНЕНИЕ И КОМНАТА</b></color>\n\n- На матч ты получаешь баннер MATCH FOUND с именем и рейтингом соперника, звук и мигание на панели задач. Надо нажать Готов - автоготовности нет.\n- У тебя 90 секунд, и когда любой игрок жмёт Готов, окно сбрасывается на свежие 90 для обоих - медленный альт-табер всегда получает полное время. Истекло - оба возвращаетесь в поиск.\n- Отклонить возвращает обоих в очередь и блокирует вашу пару от повторного матча на 5 минут. Когда комната уже выдана, отклонение больше не работает.\n- Когда оба готовы, сервер выдаёт приватную рейтинговую комнату и выбирает регион Photon: если оба клиента сообщают один домашний регион, он и побеждает; иначе перебор: живые регионы игроков, затем любой домашний, затем US.\n- Твой клиент закрепляет этот регион перед входом, так что вы оба попадаете в одну комнату, а не в две одноимённые на двух континентах.\n- Если соперник так и не пришёл: предупреждение на 15 секундах, затем автоматический возврат в меню на 60. <color=#7FE87F>Без штрафа обеим сторонам.</color>\n\n<color=#FFD94D><b>РЕЙТИНГ В ПРИВАТНОЙ КОМНАТЕ</b></color>\n\n- Игра по коду комнаты рейтинговая, когда верны три вещи: твой переключатель Ranked включён, у соперника Ranked включён, и соперник на моде. Соперник, никогда не запускавший мод, сделать игру рейтинговой не может. (Одно намеренное исключение: живая незавершённая серия с прошлой сессии сохраняет рейтинговый статус при новой встрече.)\n- В момент, когда оба мода видят друг друга, клиент регистрирует серию на сервере (<color=#7FD4FF>префлайт</color>) - серия существует и на неё можно ставить уже во время игры 1.\n- Если у любого игрока Ranked выключен, сервер отказывает серии, и ты получаешь одно уведомление: матч играется как казуальный. Казуальные игры всё равно записываются - они просто не трогают рейтинг.\n- Комнаты очереди и турниров пропускают эти проверки полностью: очередь и была согласием.\n\n<color=#FFD94D><b>СЕРИЯ</b></color>\n\n- Серию берёт первый с 2 победами в играх. <color=#7FE87F>Рейтинг движется только по завершении серии</color> - вся серия один рейтинговый исход, отдельные игры рейтинг сами не двигают никогда.\n- Нерешённая серия - хотя бы одна игра сыграна, никто не на 2 победах - <color=#7FE87F>не истекает никогда</color>. Сыграй с тем же соперником завтра или через неделю - игра 1 всё ещё в силе; твой HUD подхватывает текущий счёт, а не начинает с 0-0.\n- Правило без-истечения намеренное: окно истечения позволяло игроку при 0-1 бросить серию и пересидеть часы, уворачиваясь от поражения.\n- Нетурнирная серия, в которой не была закончена ни одна игра, бросается через 30 минут; следующая встреча начинает заново. Турнирные серии вместо этого ждут свою сетку.\n- Ставки на серию, застрявшую на 60 минут, возвращаются (кроме турнирных) - сама серия остаётся возобновимой.\n- В раунде 1 каждой игры клиент сообщает серверу живые очки. Ставки запираются, когда в игре 1 набрано 2 очка суммарно (1-1 считается), - или в момент, когда любая игра серии решена.\n\n<color=#FFD94D><b>ДИСКОННЕКТЫ</b></color>\n\nЧто делает DC, зависит от счёта, и судит его игрок, который ОСТАЛСЯ:\n\n- Ты был на матч-поинте (4 раунда), когда соперник отвалился: ты берёшь игру при текущем счёте.\n- 4-4: игра твоя, записывается как 5-4.\n- В любом другом месте - включая соперника, отвалившегося ВПЕРЕДИ, - игра отменяется. Никому победа, никому поражение.\n- Выход из игры ради своего сматченного рейтингового матча объявляется заранее и против тебя не считается никогда.\n\nПравила против злоупотреблений:\n\n- Требовать DC-победу может только тот, кто остался в комнате и видел выход другого. <color=#7FE87F>Клиент самого вышедшего не может присудить себе ничего.</color>\n- Если соперник переподключился до твоего выхода, требование снимается.\n- Если отвалились ОБА, наблюдать было некому: ни победы, ни отметки выхода. При завершённой игре на табло серия остаётся активной и возобновится при следующей встрече.\n- <color=#FF6666>Отменённая игра не стирает серию</color> - завершённые игры в силе, и серия возобновляется как выше.\n\n<color=#FFD94D><b>ПРОЦЕНТ ВЫХОДОВ</b></color>\n\n- Рейтинговый DC при осмысленной игре позади (2 и более очков или завершённый раунд в ТЕКУЩЕЙ игре), когда ни одна сторона не на матч-поинте, записывается выходом на вышедшего - максимум один на игрока за серию.\n- <color=#7FD4FF>% выходов</color> = рейтинговые DC, делённые на победы + поражения + DC рейтинговых серий. Ниже 5 процентов - зелёный, от 5 до 15 - янтарный, от 15 - красный; видно всем в таблице лидеров.\n- DC на матч-поинте становится DC-победой другого игрока, а не отметкой выхода.\n\nПолное дерево решений «записана ли игра» - см. <color=#7FD4FF>Когда игра засчитывается</color>.')
  ,  ('fc07ba40fe031c27', 'uk', '0aa41f4136b6fb6ac705d0f82fccc62a6fd86ca6', E'Рейтинговий 1v1 - серцевина мода: серії до 2 перемог (BO3), один рейтинг Glicko і два способи почати рейтингову серію - черга або приватна кімната, де обидва гравці з модом. Ця сторінка веде чергу від Пошуку до кімнати, пояснює, як приватне лобі стає рейтинговим, і що саме робить дисконект.\n\n<color=#FFD94D><b>ПОШУК СУПЕРНИКА</b></color>\n\n- Натискання «Пошук» само по собі є згодою на рейтинг - вхід у чергу вмикає Ranked для вашого акаунта.\n- Ваша смуга пошуку починається зі 100 рейтингу в обидва боки й розширюється з очікуванням: 200 після 30 секунд, 400 після 60, 800 після 120. Ширше 800 вона не стає ніколи.\n- Перетин <color=#7FD4FF>двосторонній</color>: ви маєте бути всередині смуги суперника, І він усередині вашої. Той, хто чекає 2 хвилини з широкою смугою, не схопить свіжого гравця, чия вузька смуга його виключає.\n- Серед дійсних кандидатів перемагає найближчий рейтинг.\n- Гравці, яких ви відхилили за останні 5 хвилин, гравці з блокуванням (у будь-який бік) і забанені акаунти не пропонуються ніколи.\n- Шукати, граючи звичайну гру, можна - ванільний квікплей і звичайні кімнати ваш пошук не скасовують. Вхід у будь-яку кімнату від мода (турнір, 2v2, 1v2 чи FFA) скасовує його одразу.\n- Після 30 хвилин пошуку вас прибирають із черги. <color=#8A8A93>Станьте знову, якщо ви ще тут, - клієнт 1v1 ніколи не повертає вас у чергу сам.</color>\n\n<color=#FFD94D><b>ГОТОВНІСТЬ, ВІДМОВА Й КІМНАТА</b></color>\n\n- На матчі ви отримуєте банер MATCH FOUND з ім''ям і рейтингом суперника, звук і блимання панелі завдань. Треба натиснути «Готовий» - автоготовності немає.\n- У вас 90 секунд, і коли будь-хто з двох тисне «Готовий», вікно скидається на свіжі 90 для обох - повільний альт-табер завжди отримує повний час. Якщо час вийшов, обидва повертаєтеся до пошуку.\n- Відмова повертає обох у чергу й блокує вашу пару від повторного зведення на 5 хвилин. Щойно кімнату видано, відмова більше не працює.\n- Коли обидва готові, сервер видає приватну рейтингову кімнату й вибирає регіон Photon: якщо обидва клієнти повідомляють один домашній регіон, він і перемагає; інакше відступ по черзі: живі регіони гравців, потім будь-чий домашній, потім US.\n- Ваш клієнт закріплює цей регіон перед входом, тож ви обидва потрапляєте в одну кімнату, а не у дві однойменні на двох континентах.\n- Якщо суперник так і не з''явився: попередження на 15-й секунді, потім автоматичне повернення в меню на 60-й. <color=#7FE87F>Без покарання для обох.</color>\n\n<color=#FFD94D><b>РЕЙТИНГ У ПРИВАТНІЙ КІМНАТІ</b></color>\n\n- Гра за кодом кімнати рейтингова, коли істинні три речі: ваш перемикач Ranked увімкнено, суперник має Ranked увімкненим і суперник грає з модом. Суперник, що ніколи не запускав мод, не може зробити гру рейтинговою. (Один навмисний виняток: жива незавершена серія з попередньої сесії зберігає рейтинговий статус, коли ви зустрінетеся знову.)\n- У мить, коли обидва моди бачать одне одного, клієнт реєструє серію на сервері (<color=#7FD4FF>прифлайт</color>) - тож серія існує і на неї можна ставити вже під час гри 1.\n- Якщо в когось Ranked вимкнено, сервер відмовляє серії, а ви отримуєте одне сповіщення: матч грається як звичайний. Звичайні ігри все одно записуються - вони просто не чіпають рейтинг.\n- Кімнати черги й турнірів ці перевірки пропускають цілком: згодою була сама черга.\n\n<color=#FFD94D><b>СЕРІЯ</b></color>\n\n- Серію бере перший із 2 виграними іграми. <color=#7FE87F>Рейтинг рухається лише коли серія завершується</color> - вся серія це один рейтинговий результат, і окремі ігри самі рейтинг не рухають ніколи.\n- Невирішена серія - хоч одна зіграна гра й ніхто на 2 перемогах - <color=#7FE87F>не спливає ніколи</color>. Зіграйте з тим самим суперником завтра чи наступного тижня - гра 1 досі в силі; ваш HUD підхоплює поточний рахунок замість рестарту на 0-0.\n- Це правило без-строку навмисне: вікно спливання дозволяло гравцю на 0-1 покинути серію й пересидіти годинник, щоб уникнути поразки.\n- Нетурнірна серія, де не догралася жодна гра, закидається за 30 хвилин; наступна зустріч починає з чистого. Турнірні серії натомість чекають на свою сітку.\n- Ставки на серію, що застигла на 60 хвилин, повертаються (крім турнірних серій) - сама серія лишається відновлюваною.\n- Під час раунду 1 кожної гри клієнт репортить живі очки серверу. Ставки блокуються, щойно в грі 1 набрано 2 очки сумарно (1-1 теж рахується), - або в мить, коли вирішено будь-яку гру серії.\n\n<color=#FFD94D><b>ДИСКОНЕКТИ</b></color>\n\nЩо робить DC, залежить від рахунку, і судить це гравець, який ЛИШИВСЯ:\n\n- Ви були на матч-поінті (4 раунди), коли суперник відвалився: ви виграєте гру з поточним рахунком.\n- 4-4: ви берете гру, записується 5-4.\n- Будь-де інде - включно з суперником, що відвалився, ведучи в рахунку, - гра скасовується. Ніхто не отримує ні перемоги, ні поразки.\n- Вихід із гри заради власного рейтингового матчу з черги оголошується заздалегідь і ніколи не рахується проти вас.\n\nПравила проти зловживань:\n\n- Заявити DC-перемогу може лише гравець, що лишився в кімнаті й бачив вихід іншого. <color=#7FE87F>Клієнт самого втікача не може присудити собі нічого.</color>\n- Якщо суперник перепідключиться до вашого виходу, заявка скидається.\n- Якщо відвалюються ОБИДВА, спостерігати не лишився ніхто: ні перемоги, ні позначки виходу. З дограною грою на табло серія лишається активною й відновлюється за наступної зустрічі.\n- <color=#FF6666>Скасована гра не стирає серію</color> - дограні ігри в силі, і серія відновлюється, як описано вище.\n\n<color=#FFD94D><b>ВІДСОТОК ВИХОДІВ</b></color>\n\n- Рейтинговий DC зі змістовною грою позаду (2 і більше очок або дограний раунд у ПОТОЧНІЙ грі), коли жодна сторона не на матч-поінті, записується як вихід проти втікача - щонайбільше один на гравця за серію.\n- <color=#7FD4FF>Виходи %</color> = рейтингові DC, поділені на перемоги + поразки + DC рейтингових серій. Менше 5 відсотків показується зеленим, від 5 до 15 - бурштиновим, від 15 - червоним, і це бачать усі в таблиці лідерів.\n- DC на матч-поінті натомість стає DC-перемогою іншого гравця, а не позначкою виходу.\n\nПовне дерево рішень «чи це записується» - у <color=#7FD4FF>Коли гра зараховується</color>.')
  ,  ('fc07ba40fe031c27', 'sv', '0aa41f4136b6fb6ac705d0f82fccc62a6fd86ca6', E'Ranked 1v1 är moddens kärnläge: bäst-av-3-serier, en Glicko-rating, och två sätt att starta en betygsatt serie - kön, eller ett privat rum där båda spelarna kör modden. Den här sidan täcker kön från Sök till rum, hur en privat lobby blir betygsatt, och exakt vad en frånkoppling gör.\n\n<color=#FFD94D><b>ATT HITTA EN MOTSTÅNDARE</b></color>\n\n- Att klicka på Sök är i sig Ranked-samtycket - att gå med i kön slår på Ranked för ditt konto.\n- Ditt sökband börjar på 100 rating i vardera riktning och vidgas medan du väntar: 200 efter 30 sekunder, 400 efter 60, 800 efter 120. Det vidgas aldrig förbi 800.\n- Överlappet är <color=#7FD4FF>tvåsidigt</color>: du måste vara inom din motståndares band OCH de måste vara inom ditt. En 2-minutersväntare med brett band kan inte hugga en färsk köare vars smala band utesluter dem.\n- Bland giltiga kandidater vinner den närmaste ratingen.\n- Spelare du avböjt de senaste 5 minuterna, spelare du blockerat (i endera riktningen) och bannade konton erbjuds aldrig.\n- Att söka medan du spelar casual går bra - originalets quickplay och vanliga casual-rum avbryter aldrig din sökning. Att gå med i ett modd-utfärdat rum (en turnering, 2v2, 1v2 eller FFA) gör det, omedelbart.\n- Efter 30 minuters sökning tas du bort från kön. <color=#8A8A93>Ställ dig i kön igen om du är kvar - 1v1-klienten köar aldrig om åt dig.</color>\n\n<color=#FFD94D><b>REDO, AVBÖJ OCH RUMMET</b></color>\n\n- Vid en match får du en MATCH HITTAD-banner med din motståndares namn och rating, ett ljud och en blinkning i aktivitetsfältet. Du måste klicka på Redo - det finns ingen auto-redo.\n- Du har 90 sekunder, och när endera spelaren klickar Redo nollställs fönstret till färska 90 för båda - en långsam alt-tabbare får alltid full tid. Tar tiden slut går ni båda tillbaka till sökningen.\n- Avböj sätter er båda tillbaka i kön och hindrar er två från att paras om i 5 minuter. När rummet väl utfärdats fungerar inte Avböj längre.\n- När båda är redo utfärdar servern ett privat Ranked-rum och väljer Photon-region: rapporterar båda klienterna samma hemregion vinner den; annars faller det tillbaka genom spelarnas live-regioner, sedan endera hemregionen, sedan US.\n- Din klient låser den regionen innan den går med, så ni båda landar i ett rum i stället för två rum med samma namn på två kontinenter.\n- Om din motståndare aldrig dyker upp: en varning vid 15 sekunder, sedan automatisk återgång till menyn vid 60. <color=#7FE87F>Inget straff för någon sida.</color>\n\n<color=#FFD94D><b>RANKED I ETT PRIVAT RUM</b></color>\n\n- En rumskodsmatch är betygsatt när tre saker är sanna: din Ranked-växel är på, din motståndare har Ranked aktiverat, och din motståndare kör modden. En motståndare som aldrig kört modden kan aldrig göra en match betygsatt. (Ett avsiktligt undantag: en pågående oavslutad serie från en tidigare sittning behåller sin Ranked-status när ni möts igen.)\n- I samma stund båda moddar ser varandra registrerar klienten serien hos servern (<color=#7FD4FF>preflighten</color>) - så serien finns, och går att satsa på, under match 1.\n- Om någon spelare har Ranked avstängt vägrar servern serien och du får en notis: matchen spelas ut som casual. Casual-matcher registreras fortfarande - de rör bara aldrig rating.\n- Kö- och turneringsrum hoppar över de här kontrollerna helt: att köa var samtycket.\n\n<color=#FFD94D><b>SERIEN</b></color>\n\n- Först till 2 matchvinster tar serien. <color=#7FE87F>Rating rör sig först när en serie avslutas</color> - hela serien är ett ratingutfall, och enskilda matcher flyttar aldrig rating på egen hand.\n- En oavgjord serie - minst en match spelad, ingen på 2 vinster - <color=#7FE87F>går aldrig ut</color>. Spela samma motståndare imorgon eller nästa vecka och match 1 står kvar; din HUD plockar upp ställningen i stället för att börja om på 0-0.\n- Den regeln utan utgångstid är avsiktlig: ett utgångsfönster lät en spelare i underläge 0-1 överge serien och vänta ut klockan för att slippa förlusten.\n- En icke-turneringsserie där ingen match någonsin avslutats överges efter 30 minuter; nästa möte börjar om. Turneringsserier väntar på sitt spelträd i stället.\n- Vad på en serie som stått stilla i 60 minuter återbetalas (turneringsserier undantagna) - serien själv förblir återupptagbar.\n- Under rond 1 i varje match rapporterar klienten live-poäng till servern. Vadslagningen låses när 2 poäng totalt gjorts i match 1 (1-1 räknas) - eller i samma stund någon match i serien avgörs.\n\n<color=#FFD94D><b>FRÅNKOPPLINGAR</b></color>\n\nVad en frånkoppling gör beror på ställningen, och den bedöms av spelaren som STANNADE:\n\n- Du stod på matchboll (4 ronder) när din motståndare försvann: du vinner matchen med den stående ställningen.\n- 4-4: du tar matchen, registrerad som 5-4.\n- Allt annat - även en motståndare som droppar i LEDNING - matchen ställs in. Ingen får en vinst, ingen får en förlust.\n- Att lämna en match för att gå med i din egen köade Ranked-match aviseras i förväg och räknas aldrig emot dig.\n\nAnti-missbruksreglerna:\n\n- Bara spelaren som stannade i rummet och såg den andra lämna kan göra anspråk på en DC-vinst. <color=#7FE87F>En avhoppares egen klient kan aldrig tilldela sig själv något.</color>\n- Om motståndaren återansluter innan du lämnar släpps anspråket.\n- Om BÅDA spelarna droppar stannade ingen kvar för att observera: ingen vinst, ingen avhoppsmarkering. Med en avslutad match på tavlan förblir serien aktiv och återupptas nästa gång ni möts.\n- <color=#FF6666>En inställd match suddar inte serien</color> - avslutade matcher står, och serien återupptas enligt ovan.\n\n<color=#FFD94D><b>AVHOPPSPROCENT</b></color>\n\n- En Ranked-DC med meningsfullt spel bakom sig (2 eller fler poäng, eller en avslutad rond, i den PÅGÅENDE matchen), när ingen sida står på matchboll, registreras som ett avhopp mot den som lämnade - högst ett per spelare per serie.\n- <color=#7FD4FF>Avhopps-%</color> = Ranked-DC:er delat med Ranked-serievinster + förluster + DC:er. Under 5 procent visas grönt, 5 till under 15 bärnsten, 15 och uppåt rött - synligt för alla på topplistan.\n- En DC på matchboll blir en DC-vinst för den andra spelaren i stället, inte en avhoppsmarkering.\n\nFör hela beslutsträdet om vad som registreras, se <color=#7FD4FF>När en match räknas</color>.')
  -- economy_article (d89523ad6cb44ac1)
  ,  ('d89523ad6cb44ac1', 'es', '69eb03ebb191b5b285ab8ffca88ed678a84bad0d', E'Cada juego terminado paga XP, el XP se convierte en oro a 100 XP = 1 de oro, y el juego ranked multiplica las recompensas base de abajo por el rango de tu rival. Esta es la tabla de pagos - números exactos, modo por modo. (Los premios de podio de torneo van aparte; ver <color=#7FD4FF>Plazos e incomparecencias</color>.)\n\n<color=#FFD94D><b>EL MULTIPLICADOR DE RANGO</b></color>\n\nEn juego ranked, las recompensas base se multiplican por el rango del RIVAL - <color=#7FE87F>ganes o pierdas. Jugar hacia arriba siempre paga.</color>\n\n<color=#7FD4FF>Principiante</color> (menos de 1500) - x1.0\n<color=#7FD4FF>Intermedio</color> (1500 o más) - x1.5\n<color=#7FD4FF>Avanzado</color> (1675 o más) - x2.0\n<color=#7FD4FF>Maestro</color> (1980 o más) - x2.5\n<color=#7FD4FF>Gran Maestro</color> (2330 o más) - x3.0\n\nAplica al XP y al oro de serie, y un rival sin rating registrado cuenta como 1500 (x1.5). Cuál es ''el rating del rival'': su rating 1v1 en 1v1, el rating 2v2 medio del equipo contrario en 2v2, el rating 1v1 medio del asiento contrario en 1v2, y el rating FFA medio de tus rivales en FFA.\n\n<color=#FFD94D><b>1v1</b></color>\n\nPor juego, los multiplicadores se apilan y el total se trunca a número entero:\n\n- Base de <color=#7FE87F>250 XP</color> por juego terminado, casual incluido.\n- Victoria del juego: x1.5. Ranked: x1.5. Rango del rival: x1.0 a x3.0 (solo ranked).\n- Una victoria por barrida (rival a 0 rondas) añade +100 XP planos, después de los multiplicadores.\n\nEjemplos exactos: derrota casual 250, victoria casual 375; derrota ranked vs un Principiante 375; victoria ranked vs un Principiante 562, vs un Intermedio 843, vs un Gran Maestro 1687 (+100 más si es 5-0).\n\nOro de serie, solo BO3 ranked - el juego casual no crea series y no paga ninguno:\n\n- Perdedor: 5 x rango del rival, truncado. Ganador: el doble.\n- El ganador dobla OTRA VEZ si el derrotado está ahora mismo en el top 3 de la clasificación.\n- +2 planos encima por un 2-0.\n- Ganador/perdedor por rango del rival, antes de podio y barrida: Principiante 10/5, Intermedio 14/7, Avanzado 20/10, Maestro 24/12, Gran Maestro 30/15.\n\n<color=#FFD94D><b>2v2</b></color>\n\n- Por juego: 600 XP x el rango del equipo contrario, luego x1.5 si tu equipo ganó el juego.\n- Sala por defecto todo-1500: 900 XP por derrota, 1350 por victoria.\n- Oro de serie: 50 (cada ganador) o 25 (cada perdedor), x el rango del equipo contrario. Sala por defecto: 75/37.\n\n<color=#FFD94D><b>1v2</b></color>\n\nBase de 500 XP por juego, x1.5 al ganar, y luego un multiplicador de dificultad por asiento:\n\n- Asiento del solo: x1.5.\n- Solo que juega SIN la ventaja de carta extra: otro x1.20.\n- Asientos del dúo frente a un solo potenciado (carta extra activa): x1.10.\n- Rango del rival, leído del rating 1v1 medio del asiento contrario - 1v2 no tiene rating propio.\n- Rival ahora mismo en el top 3 de la clasificación 1v2: x1.35, ganes o pierdas.\n- El producto entero tiene tope en x4.0; el bonus de victoria x1.5 aplica encima del tope.\n\nPor defecto con la carta extra activa: el solo gana 1125 XP por derrota y 1687 por victoria; cada miembro del dúo 825/1237.\n\nOro de serie: 40 (lado ganador) o 20 (lado perdedor), x solo el rango del rival - el asiento, la ventaja y el podio viven en el XP. Por defecto: 60/30.\n\n<color=#FFD94D><b>FFA - EL MEDIDOR</b></color>\n\nFFA paga por PELEAR, no por tiempo en la sala. La fórmula, en versión legible:\n\n- La unidad de trabajo son las <color=#7FD4FF>batallas</color>: cada ronda decisiva anotada por cualquiera en el juego. <color=#FF6666>Acampar no añade nada al bote</color>, y el recorte de último puesto que gana es la parte más pequeña de lo que generaron los demás.\n- Un techo de ritmo limita la velocidad a la que se cobran las batallas. Para una sala de P jugadores, se espera una batalla cada 3.08 + 6.54 x P segundos aproximadamente (P contado como mínimo 3 y máximo 6 aquí), y el juego paga como mucho el DOBLE de ese ritmo sobre el tiempo transcurrido del juego en el reloj del servidor - estancarse o farmear puntos no puede superarlo.\n- La tasa base es 3.5 de oro por jugador-minuto, +5% por cada jugador por encima de 4. Un FFA de 10 jugadores es la mejor tasa de oro del juego.\n- El puesto da forma a tu parte del bote: el 1.er puesto gana 1.666x la media de la sala, el último 0.334x - una horquilla de unas 5x. Los jugadores que comparten puesto comparten la misma parte.\n- Un campo más fuerte multiplica el bote: el rango medio de tus rivales dividido por 1.5, así que un campo por defecto de 1500 es exactamente x1.0. Las salas casual toman el factor mínimo (unas x0.667) y nunca tocan ratings.\n- El bote es una cantidad de oro. El 55% se paga directamente como Oro de puesto (mínimo 1). El otro 45% se paga como XP a 100 XP por punto de bote (mínimo 50 XP), que gotea de vuelta como oro por la conversión normal.\n- El puesto en sí ordena por puntos, luego todas las rondas ganadas (las gastadas incluidas), luego kills donde el desempate por kills de la sala esté activo; los empates restantes comparten puesto.\n- Los fantasmas y los que salieron pronto con gracia no cobran ni puntúan ese juego: irse antes de que el campo anotara 2 medios puntos, con tu propio recuento (puntos, medios puntos, kills) aún a cero, te saca de él por completo.\n\n<color=#FFD94D><b>NIVELES Y EL GOTEO DE XP A ORO</b></color>\n\n- El XP se convierte a <color=#7FE87F>100 XP = 1 de oro</color>, pagado cada vez que tu total acumulado cruza una centena. El XP de todos los modos - premios de torneo incluidos - alimenta el mismo total.\n- Subir al nivel L cuesta 100 x L^1.5 XP, truncado: el nivel 2 cuesta 282, el 5 cuesta 1118, el 10 cuesta 3162, el 50 cuesta 35355, el 100 cuesta 100000. El nivel máximo es 100.\n- Entrar en un nivel múltiplo de 5 paga oro extra: <color=#7FE87F>100g para los niveles 5 a 50, 500g para los 55 a 100</color> - 6000g de por vida si llegas al tope. Cae en el momento en que cualquier XP dispara el nivel - cualquier modo, premios de torneo incluidos; una subida durante un juego FFA aparece dentro del +g de ese juego.\n\n<color=#FFD94D><b>ORO DE LOGROS</b></color>\n\nCada logro paga <color=#7FE87F>100g</color> salvo que esté listado aquí:\n\n- <color=#7FD4FF>1000g</color> - Sid Slayer, Stan Slayer, Gran Maestro (llegar a 2330), Touch Grass, Babel.\n- <color=#7FD4FF>500g</color> - Maestro (llegar a 1980), Barrida en equipo, Renacer de las cenizas, Conquistador casual, ¡Gemelos!, Inmortal, Adquisición hostil, Bajas, Campeón Sync, Campeón Async.\n- <color=#7FD4FF>300g</color> - Baraja trucada, Impecable, Silly Drill, De cabeza a lo hondo, Club de los cien, Imparable, Aguafiestas, Corazón roto, Dragomán, Finalista Sync, Finalista Async.\n\nLos 5-0 de FFA se anidan: una victoria 5-0 con 5 jugadores que terminan paga Limpieza general (100g) + Aguafiestas (300g) + Adquisición hostil (500g) en un solo juego. Los logros de traductor (Rosetta, Dragomán, Babel) se disparan a las 10, 100 y 1000 cadenas vivas aprobadas.\n\n<color=#8A8A93>Fuera de las partidas: los boosters del servidor de Discord cobran 2000g mensuales, y los artistas de la comunidad ganan un 30% de comisión (redondeada hacia abajo a oro entero) cuando otro jugador compra su pieza - los regalos no pagan.</color>')
  ,  ('d89523ad6cb44ac1', 'ru', '69eb03ebb191b5b285ab8ffca88ed678a84bad0d', E'Каждая завершённая игра платит XP, XP конвертируется в золото по курсу 100 XP = 1 золото, а рейтинговая игра умножает базовые награды ниже на тир ранга соперника. Это таблица оплаты - точные числа, режим за режимом. (Призы турнирного подиума отдельно; см. <color=#7FD4FF>Дедлайны и техпоражения</color>.)\n\n<color=#FFD94D><b>МНОЖИТЕЛЬ ТИРА</b></color>\n\nВ рейтинговой игре базовые награды умножаются на тир ранга СОПЕРНИКА - <color=#7FE87F>при победе и при поражении. Играть вверх всегда выгодно.</color>\n\n<color=#7FD4FF>Новичок</color> (ниже 1500) - x1.0\n<color=#7FD4FF>Средний</color> (1500 и выше) - x1.5\n<color=#7FD4FF>Продвинутый</color> (1675 и выше) - x2.0\n<color=#7FD4FF>Мастер</color> (1980 и выше) - x2.5\n<color=#7FD4FF>Грандмастер</color> (2330 и выше) - x3.0\n\nОн применяется к XP и к золоту за серию, а соперник без рейтинга считается за 1500 (x1.5). Чей рейтинг считается «рейтингом соперника»: его рейтинг 1v1 в 1v1, средний рейтинг 2v2 команды соперников в 2v2, средний рейтинг 1v1 противоположной стороны в 1v2 и средний рейтинг FFA твоих соперников в FFA.\n\n<color=#FFD94D><b>1v1</b></color>\n\nЗа игру, множители стакаются, затем итог усекается до целого:\n\n- База <color=#7FE87F>250 XP</color> за завершённую игру, включая казуальные.\n- Победа в игре: x1.5. Рейтинговая: x1.5. Тир соперника: от x1.0 до x3.0 (только в рейтинге).\n- Сухая победа (соперник на 0 раундов) добавляет плоские +100 XP, после множителей.\n\nТочные примеры: казуальное поражение 250, казуальная победа 375; рейтинговое поражение Новичку 375; рейтинговая победа над Новичком 562, над Средним 843, над Грандмастером 1687 (+100 сверху при 5-0).\n\nЗолото за серию, только рейтинговый BO3 - казуальная игра серий не создаёт и золота не платит:\n\n- Проигравший: 5 x тир соперника, усечённо. Победитель: вдвое больше.\n- Победитель удваивает ЕЩЁ РАЗ, если побеждённый сейчас сидит в топ-3 таблицы лидеров.\n- Плоские +2 сверху за сухие 2-0.\n- Победитель/проигравший по тиру соперника, до подиума и 2-0: Новичок 10/5, Средний 14/7, Продвинутый 20/10, Мастер 24/12, Грандмастер 30/15.\n\n<color=#FFD94D><b>2v2</b></color>\n\n- За игру: 600 XP x тир команды соперников, затем x1.5, если твоя команда выиграла игру.\n- Стандартное лобби всех-по-1500: 900 XP за поражение, 1350 за победу.\n- Золото за серию: 50 (каждому победителю) или 25 (каждому проигравшему), x тир команды соперников. Стандартное лобби: 75/37.\n\n<color=#FFD94D><b>1v2</b></color>\n\nБаза 500 XP за игру, x1.5 при победе, затем множитель сложности на слот:\n\n- Слот соло: x1.5.\n- Соло, играющий БЕЗ гандикапа доп. пика: ещё x1.20.\n- Слоты дуо против усиленного соло (доп. пик включён): x1.10.\n- Тир соперника читается из среднего рейтинга 1v1 противоположной стороны - у 1v2 нет собственного рейтинга.\n- Соперник сейчас в топ-3 таблицы 1v2: x1.35, при победе и поражении.\n- Всё произведение ограничено x4.0; бонус за победу x1.5 идёт поверх потолка.\n\nСтандартно при включённом доп. пике: соло получает 1125 XP за поражение и 1687 за победу; каждый в дуо - 825/1237.\n\nЗолото за серию: 40 (победившая сторона) или 20 (проигравшая), x только тир соперника - факторы места, гандикапа и подиума живут на XP. Стандартно: 60/30.\n\n<color=#FFD94D><b>FFA - СЧЁТЧИК</b></color>\n\nFFA платит за ДРАКУ, а не за время в лобби. Формула, в читаемом виде:\n\n- Единица работы - <color=#7FD4FF>битвы</color>: каждый решающий раунд, взятый кем угодно в игре. <color=#FF6666>Кемпинг ничего не добавляет в банк</color>, а срез последнего места, который он приносит, - наименьшая доля того, что нагенерировали остальные.\n- Потолок темпа ограничивает скорость обналичивания битв. Для лобби из P игроков одна битва ожидается примерно каждые 3.08 + 6.54 x P секунд (P здесь берётся не меньше 3 и не больше 6), и игра платит максимум за ВДВОЕ больший темп по прошедшему времени на часах сервера - затяжка или фарм очков его не обгонят.\n- Базовая ставка - 3.5 золота за игроко-минуту, +5% за каждого игрока сверх 4. FFA на 10 игроков - лучший курс золота в игре.\n- Место формирует твою долю банка: 1-е место получает 1.666x среднего по лобби, последнее - 0.334x, разброс примерно в 5 раз. Делящие место делят одинаковую долю.\n- Более сильное поле умножает котёл: средний тир твоих соперников, делённый на 1.5, так что стандартное поле 1500 - ровно x1.0. Казуальные лобби берут нижний фактор (около x0.667) и рейтинги не трогают вовсе.\n- Банк - это сумма золота. 55% платится напрямую как золото за место (минимум 1). Остальные 45% платятся как XP по 100 XP за очко банка (минимум 50 XP), которые обычной конверсией капают обратно золотом.\n- Само место сортируется по очкам, затем по всем заработанным выигранным раундам (включая потраченные), затем по убийствам там, где в лобби включён тайбрейк по убийствам; оставшиеся ничьи делят место.\n- Призраки и прощённые ранние выходы за ту игру не оплачиваются и не рейтингуются: выход до 2 набранных полем полуочков при собственном нулевом счёте (очки, полуочки, убийства) выводит из неё полностью.\n\n<color=#FFD94D><b>УРОВНИ И КАПЕЛЬНИЦА XP-В-ЗОЛОТО</b></color>\n\n- XP конвертируется по курсу <color=#7FE87F>100 XP = 1 золото</color> и выплачивается каждый раз, когда твоя сумма пересекает сотню. XP каждого режима - включая турнирные призы - питает один общий счёт.\n- Подъём на уровень L стоит 100 x L^1.5 XP, усечённо: уровень 2 стоит 282, уровень 5 - 1118, уровень 10 - 3162, уровень 50 - 35355, уровень 100 - 100000. Максимальный уровень - 100.\n- Вход на уровень, кратный 5, платит бонусное золото: <color=#7FE87F>100g за уровни с 5 по 50, 500g за 55-100</color> - 6000g за всю жизнь, если добраться до потолка. Оно падает в момент, когда любая награда XP пробивает уровень - в любом режиме, включая турнирные призы; уровень, взятый во время игры FFA, попадает внутрь числа +g этой игры.\n\n<color=#FFD94D><b>ЗОЛОТО ЗА ДОСТИЖЕНИЯ</b></color>\n\nКаждое достижение платит <color=#7FE87F>100g</color>, если не указано здесь:\n\n- <color=#7FD4FF>1000g</color> - Sid Slayer, Stan Slayer, Грандмастер (достигни 2330), Потрогай траву, Вавилон.\n- <color=#7FD4FF>500g</color> - Мастер (достигни 1980), Командный разгром, Восставший из пепла, Покоритель казуала, Близнецы!, Бессмертный, Враждебное поглощение, Убийства, Чемпион Sync, Чемпион Async.\n- <color=#7FD4FF>300g</color> - Краплёная колода, Безупречный, Silly Drill, С головой в омут, Клуб сотни, Неудержимый, Незваный гость, Разбитое сердце, Драгоман, Финалист Sync, Финалист Async.\n\nСухие победы FFA вложены: одна победа 5-0, где доиграли 5 игроков, платит Генеральную уборку (100g) + Незваного гостя (300g) + Враждебное поглощение (500g) за одну игру. Достижения переводчика (Розетта, Драгоман, Вавилон) срабатывают на 10, 100 и 1000 одобренных живых строк.\n\n<color=#8A8A93>Вне матчей: бустеры Discord-сервера получают 2000g ежемесячно, а художники сообщества - роялти 30% (округляется вниз до целого золота), когда их предмет покупает другой игрок; подарки не платят ничего.</color>')
  ,  ('d89523ad6cb44ac1', 'uk', '69eb03ebb191b5b285ab8ffca88ed678a84bad0d', E'Кожна дограна гра платить XP, XP конвертується в золото за курсом 100 XP = 1 золото, а рейтингова гра множить базові нагороди нижче на рівень рангу суперника. Це таблиця виплат - точні числа, режим за режимом. (Турнірні призи п''єдесталу окремо; див. <color=#7FD4FF>Дедлайни й технічні поразки</color>.)\n\n<color=#FFD94D><b>МНОЖНИК РІВНЯ</b></color>\n\nУ рейтинговій грі базові нагороди множаться на рівень рангу СУПЕРНИКА - <color=#7FE87F>перемога чи поразка. Грати проти сильніших завжди вигідно.</color>\n\n<color=#7FD4FF>Початківець</color> (менше 1500) - x1.0\n<color=#7FD4FF>Середній</color> (1500 і більше) - x1.5\n<color=#7FD4FF>Просунутий</color> (1675 і більше) - x2.0\n<color=#7FD4FF>Майстер</color> (1980 і більше) - x2.5\n<color=#7FD4FF>Грандмайстер</color> (2330 і більше) - x3.0\n\nВін застосовується до XP і до золота за серію, а суперник без рейтингу в записах рахується як 1500 (x1.5). Що вважається «рейтингом суперника»: його рейтинг 1v1 в 1v1, середній рейтинг 2v2 команди суперників у 2v2, середній рейтинг 1v1 протилежного місця в 1v2 і середній рейтинг FFA ваших суперників у FFA.\n\n<color=#FFD94D><b>1v1</b></color>\n\nЗа гру множники стакаються, потім сума обрізається до цілого:\n\n- База <color=#7FE87F>250 XP</color> за дограну гру, включно зі звичайними.\n- Перемога в грі: x1.5. Рейтингова: x1.5. Рівень суперника: від x1.0 до x3.0 (лише рейтингові).\n- Суха перемога (суперник на 0 раундів) додає рівно +100 XP після множників.\n\nТочні приклади: звичайна поразка 250, звичайна перемога 375; рейтингова поразка проти Початківця 375; рейтингова перемога проти Початківця 562, проти Середнього 843, проти Грандмайстра 1687 (+100 зверху за 5-0).\n\nЗолото за серію, лише рейтингові BO3 - звичайна гра серій не створює і золота за них не платить:\n\n- Переможений: 5 x рівень суперника, обрізано до цілого. Переможець: удвічі більше.\n- Переможець подвоює ЩЕ РАЗ, якщо переможений зараз сидить у топ-3 таблиці лідерів.\n- Рівно +2 зверху за суху серію 2-0.\n- Переможець/переможений за рівнем суперника, до п''єдесталу й 2-0: Початківець 10/5, Середній 14/7, Просунутий 20/10, Майстер 24/12, Грандмайстер 30/15.\n\n<color=#FFD94D><b>2v2</b></color>\n\n- За гру: 600 XP x рівень команди суперників, потім x1.5, якщо ваша команда виграла гру.\n- Стандартне лобі всіх-по-1500: 900 XP за поразку, 1350 за перемогу.\n- Золото за серію: 50 (кожному переможцю) або 25 (кожному переможеному), x рівень команди суперників. Стандартне лобі: 75/37.\n\n<color=#FFD94D><b>1v2</b></color>\n\nБаза 500 XP за гру, x1.5 за перемогу, потім множник складності за місцем:\n\n- Місце соло: x1.5.\n- Соло, що грає БЕЗ фори додаткового вибору: ще x1.20.\n- Місця дуо проти підсиленого соло (додатковий вибір увімкнено): x1.10.\n- Рівень суперника береться із середнього рейтингу 1v1 протилежного місця - власного рейтингу в 1v2 немає.\n- Суперник зараз у топ-3 таблиці лідерів 1v2: x1.35, перемога чи поразка.\n- Увесь добуток обмежено x4.0; бонус за перемогу x1.5 діє поверх ліміту.\n\nСтандартно з увімкненим додатковим вибором: соло заробляє 1125 XP за поразку і 1687 за перемогу; кожен із дуо 825/1237.\n\nЗолото за серію: 40 (стороні-переможцю) або 20 (стороні, що програла), лише x рівень суперника - множники місця, фори й п''єдесталу живуть на XP. Стандартно: 60/30.\n\n<color=#FFD94D><b>FFA - ЛІЧИЛЬНИК</b></color>\n\nFFA платить за БОРОТЬБУ, а не за час у лобі. Формула в читабельному вигляді:\n\n- Одиниця роботи - <color=#7FD4FF>битви</color>: кожен вирішальний раунд, зарахований будь-ким у грі. <color=#FF6666>Кемпінг нічого не додає в банк</color>, а частка останнього місця, яку він заробляє, - найменший шматок згенерованого рештою.\n- Стеля темпу обмежує, як швидко битви переводяться в гроші. Для лобі з P гравців одна битва очікується приблизно кожні 3.08 + 6.54 x P секунд (P тут береться щонайменше 3 і щонайбільше 6), і гра платить щонайбільше ПОДВІЙНИЙ такий темп за час гри на годиннику сервера - затягування чи фарм очок його не обженуть.\n- Базовий курс - 3.5 золота за гравцехвилину, +5% за кожного гравця понад 4. FFA на 10 гравців - найкращий курс золота в грі.\n- Місце формує вашу частку банку: 1-ше заробляє 1.666x середнього по лобі, останнє - 0.334x - розкид приблизно в 5 разів. Гравці, що ділять місце, ділять і частку.\n- Сильніший склад множить банк: середній рівень ваших суперників, поділений на 1.5, тож стандартне поле 1500 - рівно x1.0. Звичайні лобі беруть нижній множник (близько x0.667) і рейтингів не чіпають.\n- Банк - це сума золота. 55% виплачується напряму як золото за місце (мінімум 1). Решта 45% платиться як XP по 100 XP за одиницю банку (мінімум 50 XP) і скрапує назад золотом через звичайну конвертацію.\n- Саме місце сортується за очками, далі за всіма виграними раундами (включно з витраченими), далі за вбивствами там, де в лобі активний тай-брейк за вбивствами; нерозв''язані нічиї ділять місце.\n- Привиди й ті, хто вийшов рано під пільгу, за ту гру не отримують ні оплати, ні рейтингу: вихід до 2 половинок очка в полі, поки ваш власний рахунок (очки, половинки, вбивства) ще нульовий, повністю виводить вас із неї.\n\n<color=#FFD94D><b>РІВНІ ТА КРАПЛИНИ XP-В-ЗОЛОТО</b></color>\n\n- XP конвертується за курсом <color=#7FE87F>100 XP = 1 золото</color> і платиться щоразу, коли ваша поточна сума перетинає сотню. XP кожного режиму - включно з турнірними призами - живить ту саму суму.\n- Підйом на рівень L коштує 100 x L^1.5 XP, обрізано до цілого: рівень 2 коштує 282, рівень 5 - 1118, рівень 10 - 3162, рівень 50 - 35355, рівень 100 - 100000. Максимальний рівень - 100.\n- Вхід на рівень, кратний 5, платить бонусне золото: <color=#7FE87F>100g за рівні з 5 по 50, 500g з 55 по 100</color> - 6000g за весь час, якщо дійдете до стелі. Воно падає в мить, коли будь-яка нагорода XP пробиває рівень - у будь-якому режимі, включно з турнірними призами; рівень, узятий під час гри FFA, показується всередині +g тієї гри.\n\n<color=#FFD94D><b>ЗОЛОТО ЗА ДОСЯГНЕННЯ</b></color>\n\nКожне досягнення платить <color=#7FE87F>100g</color>, крім перелічених тут:\n\n- <color=#7FD4FF>1000g</color> - Sid Slayer, Stan Slayer, Грандмайстер (досягти 2330), Торкніться трави, Вавилон.\n- <color=#7FD4FF>500g</color> - Майстер (досягти 1980), Командний розгром, Повсталий з попелу, Підкорювач звичайних, Близнюки!, Безсмертний, Вороже поглинання, Убивства, Чемпіон Sync, Чемпіон Async.\n- <color=#7FD4FF>300g</color> - Підтасована колода, Бездоганний, Silly Drill, З головою у вир, Клуб сотні, Нестримний, Незваний гість, Розбите серце, Драгоман, Фіналіст Sync, Фіналіст Async.\n\nСухі перемоги FFA вкладені: одна перемога 5-0, де дограли 5 гравців, платить Генеральне прибирання (100g) + Незваний гість (300g) + Вороже поглинання (500g) за одну гру. Досягнення перекладача (Розетта, Драгоман, Вавилон) спрацьовують на 10, 100 і 1000 схвалених живих рядків.\n\n<color=#8A8A93>Поза матчами: бустери сервера Discord отримують 2000g щомісяця, а художники спільноти заробляють роялті 30% (округлені вниз до цілого золота), коли їхній предмет купує інший гравець - подарунки не платять нічого.</color>')
  ,  ('d89523ad6cb44ac1', 'sv', '69eb03ebb191b5b285ab8ffca88ed678a84bad0d', E'Varje avslutad match betalar XP, XP omvandlas till guld enligt 100 XP = 1 guld, och Ranked-spel multiplicerar basbelöningarna nedan med din motståndares ranktier. Detta är betaltabellen - exakta siffror, läge för läge. (Turneringarnas pallpriser är separata; se <color=#7FD4FF>Deadlines & walkover</color>.)\n\n<color=#FFD94D><b>TIERMULTIPLIKATORN</b></color>\n\nI Ranked-spel multipliceras basbelöningarna med MOTSTÅNDARENS ranktier - <color=#7FE87F>oavsett vinst eller förlust. Att spela uppåt lönar sig alltid.</color>\n\n<color=#7FD4FF>Nybörjare</color> (under 1500) - x1.0\n<color=#7FD4FF>Medel</color> (1500 eller mer) - x1.5\n<color=#7FD4FF>Avancerad</color> (1675 eller mer) - x2.0\n<color=#7FD4FF>Mästare</color> (1980 eller mer) - x2.5\n<color=#7FD4FF>Stormästare</color> (2330 eller mer) - x3.0\n\nDen gäller XP och serieguld, och en motståndare utan registrerad rating räknas som 1500 (x1.5). Vad som är ''motståndarens'' rating: deras 1v1-rating i 1v1, motståndarlagets snitt-2v2-rating i 2v2, motståndarsidans snitt-1v1-rating i 1v2, och dina motståndares snitt-FFA-rating i FFA.\n\n<color=#FFD94D><b>1v1</b></color>\n\nPer match, multiplikatorerna staplas, sedan trunkeras totalen till ett heltal:\n\n- Bas <color=#7FE87F>250 XP</color> per avslutad match, casual inräknat.\n- Matchvinst: x1.5. Ranked: x1.5. Motståndartier: x1.0 till x3.0 (endast Ranked).\n- En utklassningsvinst (motståndaren på 0 ronder) ger +100 XP platt, efter multiplikatorerna.\n\nExakta exempel: casual-förlust 250, casual-vinst 375; Ranked-förlust mot en Nybörjare 375; Ranked-vinst mot en Nybörjare 562, mot en Medel 843, mot en Stormästare 1687 (+100 till vid 5-0).\n\nSerieguld, endast Ranked-BO3 - casual-spel skapar ingen serie och betalar inget:\n\n- Förloraren: 5 x motståndartier, trunkerat. Vinnaren: det dubbla.\n- Vinnaren dubblar IGEN om den besegrade spelaren just nu sitter i topplistans topp 3.\n- +2 platt ovanpå för en 2-0-svepning.\n- Vinnare/förlorare per motståndartier, före pall och svep: Nybörjare 10/5, Medel 14/7, Avancerad 20/10, Mästare 24/12, Stormästare 30/15.\n\n<color=#FFD94D><b>2v2</b></color>\n\n- Per match: 600 XP x motståndarlagets tier, sedan x1.5 om ditt lag vann matchen.\n- Standardlobby där alla ligger på 1500: 900 XP för en förlust, 1350 för en vinst.\n- Serieguld: 50 (varje vinnare) eller 25 (varje förlorare), x motståndarlagets tier. Standardlobby: 75/37.\n\n<color=#FFD94D><b>1v2</b></color>\n\nBas 500 XP per match, x1.5 vid vinst, sedan en svårighetsmultiplikator per plats:\n\n- Soloplatsen: x1.5.\n- Solo som spelar UTAN extraval-handikappet: ytterligare x1.20.\n- Duoplatser som möter en buffad solo (extraval på): x1.10.\n- Motståndartier, läst från motståndarsidans snitt-1v1-rating - 1v2 har ingen egen rating.\n- Motståndare som just nu är i 1v2-topplistans topp 3: x1.35, oavsett vinst eller förlust.\n- Hela produkten har ett tak på x4.0; vinstbonusen x1.5 appliceras ovanpå taket.\n\nStandardvärden med extraval på: solospelaren tjänar 1125 XP för en förlust och 1687 för en vinst; varje duomedlem 825/1237.\n\nSerieguld: 40 (vinnande sidan) eller 20 (förlorande sidan), x enbart motståndartier - plats-, handikapp- och pallfaktorerna ligger på XP:n. Standard: 60/30.\n\n<color=#FFD94D><b>FFA - MÄTAREN</b></color>\n\nFFA betalar för STRIDEN, inte för tid i lobbyn. Formeln, i läsbar form:\n\n- Arbetsenheten är <color=#7FD4FF>strider</color>: varje avgörande rond som någon i matchen vinner. <color=#FF6666>Campande tillför inget till potten</color>, och sistaplatsandelen det ger är den minsta andelen av vad alla andra genererade.\n- Ett taktak begränsar hur snabbt strider kan lösas in. För en lobby med P spelare förväntas en strid ungefär var 3.08 + 6.54 x P sekund (P räknas som minst 3 och högst 6 här), och matchen betalar som mest för DUBBLA den takten över matchens förflutna tid på serverns klocka - att förhala eller poängfarma kan inte springa ifrån det.\n- Basnivån är 3.5 guld per spelarminut, +5% för varje spelare över 4. En 10-spelar-FFA är den bästa guldtakten i spelet.\n- Placeringen formar din andel av potten: 1:a plats tjänar 1.666x lobbysnittet, sista plats 0.334x - ungefär en 5x spridning. Spelare som delar placering delar samma andel.\n- Ett starkare fält multiplicerar potten: dina motståndares snitt-tier delat med 1.5, så ett standardfält på 1500 är exakt x1.0. Casual-lobbyer tar bottenfaktorn (ungefär x0.667) och rör aldrig ratingar.\n- Potten är ett guldbelopp. 55% betalas direkt som placeringsguld (minst 1). Övriga 45% betalas som XP med 100 XP per pottpoäng (minst 50 XP), vilket droppar tillbaka som guld genom den vanliga omvandlingen.\n- Själva placeringen sorterar på poäng, sedan alla intjänade rondvinster (även spenderade), sedan kills där lobbyns kill-tiebreak är aktiv; kvarvarande oavgjorda delar placering.\n- Spöken och tidiga avhoppare med respit får varken betalning eller rating för den matchen: att lämna innan fältet tagit 2 halvpoäng, medan din egen räkning (poäng, halvpoäng, kills) fortfarande är noll, tar dig helt ur den.\n\n<color=#FFD94D><b>NIVÅER OCH XP-TILL-GULD-DROPPET</b></color>\n\n- XP omvandlas enligt <color=#7FE87F>100 XP = 1 guld</color>, utbetalt varje gång din löpande total passerar ett hundratal. Varje läges XP - turneringspriser inräknade - matar samma total.\n- Att klättra till nivå L kostar 100 x L^1.5 XP, trunkerat: nivå 2 kostar 282, nivå 5 kostar 1118, nivå 10 kostar 3162, nivå 50 kostar 35355, nivå 100 kostar 100000. Maxnivån är 100.\n- Att gå in i en nivå delbar med 5 betalar bonusguld: <color=#7FE87F>100g för nivå 5 till 50, 500g för 55 till 100</color> - 6000g över en livstid om du når taket. Det landar i samma ögonblick som någon XP-utdelning dinger nivån - vilket läge som helst, turneringspriser inräknade; en ding under en FFA-match syns inne i den matchens +g-siffra.\n\n<color=#FFD94D><b>PRESTATIONSGULD</b></color>\n\nVarje prestation betalar <color=#7FE87F>100g</color> om den inte listas här:\n\n- <color=#7FD4FF>1000g</color> - Sid Slayer, Stan Slayer, Stormästare (nå 2330), Touch Grass, Babel.\n- <color=#7FD4FF>500g</color> - Mästare (nå 1980), Lagutklassning, Upp ur askan, Casual-erövrare, Tvillingar!, Odödlig, Fientligt övertagande, Dödstal, Sync-mästare, Async-mästare.\n- <color=#7FD4FF>300g</color> - Riggad kortlek, Felfri, Silly Drill, Ut på djupt vatten, Hundraklubben, Ostoppbar, Objuden gäst, Krossat hjärta, Dragoman, Sync-finalist, Async-finalist.\n\nFFA-utklassningarna är nästlade: en 5-0-vinst med 5 spelare som spelar klart betalar Storstädning (100g) + Objuden gäst (300g) + Fientligt övertagande (500g) i en enda match. Översättarprestationerna (Rosetta, Dragoman, Babel) utlöses vid 10, 100 och 1000 godkända live-strängar.\n\n<color=#8A8A93>Utanför matcher: Discord-serverboostare betalas 2000g i månaden, och communityns konstnärer tjänar 30% i royalty (avrundat nedåt till helt guld) när en annan spelare köper deras föremål - gåvor betalar inget.</color>')
  -- cosmetics_article (7d2c24d463786026)
  ,  ('7d2c24d463786026', 'es', '19329ffd6e3b0670e93678c0dfd1bde7861598fa', E'Los cosméticos viven en la pestaña Tienda de F5 y se compran con el oro que ganas jugando. Esta página cubre cada tipo, cómo se equipa cada uno, cómo funcionan los drops y el stock, y de dónde sale el arte.\n\n<color=#FFD94D><b>QUÉ HACE CADA TIPO</b></color>\n\n<color=#7FD4FF>Títulos</color> - la etiqueta junto a tu nombre en las superficies del mod (ver <color=#7FD4FF>Títulos</color>).\n<color=#7FD4FF>Estelas</color> - una estela de color tras tu cuerpo en las partidas. La longitud escala con el precio: las estelas de 3000 de oro son cortas, las de 5000 medianas, las de 10000 largas.\n<color=#7FD4FF>Skins de mapa</color> - recolorean todo el mapa y el fondo. Equipa cuantas quieras y cíclalas en plena partida con Shift izquierdo. El catálogo tiene recolores al estilo de los seis arts vanilla, más de treinta presets originales incluido el pack nocturno, y tres skins premium con destellos: Áureo, Platino y Aurora. <color=#7FE87F>Las skins de mapa son solo tuyas</color> - nunca se envían a otros jugadores, así que cada jugador ve su propia elección.\n<color=#7FD4FF>Estilo de nombre</color> - estilos apilables sobre tu nombre visible. El formato (negrita, cursiva, subrayado, tachado, flotar) se apila libremente; brillo, tamaño, transformación y tipografía admiten uno cada uno, y los efectos de color (sólidos, neones, arcoíris, degradados por letra) comparten un solo hueco.\n<color=#7FD4FF>Colores de jugador</color> - sustituyen tu naranja o azul de equipo por un color propio, y se vuelven tu identidad de equipo en pantallas con mod (ver <color=#7FD4FF>Colores de equipo y cuerpo</color>).\n<color=#7FD4FF>Colores de cursor</color> - recolorean tu cursor del ratón. La FORMA del cursor (por defecto, flecha, punto, mira, círculo) es una preferencia gratis. Nadie más ve nunca tu cursor.\n<color=#7FD4FF>Efectos de jugador</color> - un aura de partículas que sigue tu cuerpo en las partidas.\n<color=#7FD4FF>Caras</color> - ojos, bocas y accesorios personalizados que se insertan en el editor de personaje propio de ROUNDS junto a las piezas vanilla, y se renderizan allá donde se renderiza una cara. Algunas están animadas; el ajuste Cosméticos animados las fija a un fotograma quieto si lo prefieres.\n<color=#7FD4FF>Ocultar oro</color> - un interruptor de utilidad que enmascara tu oro en las superficies de clasificación.\n\n<color=#FFD94D><b>EQUIPAR</b></color>\n\n- De uno en uno: títulos, estelas, colores de jugador, colores de cursor y efectos de jugador usan <color=#7FD4FF>Activar</color> / <color=#7FD4FF>Desequipar</color>.\n- Multi-equipo: los estilos de nombre y las skins de mapa usan <color=#7FD4FF>Equipar</color> / <color=#7FD4FF>Quitar</color> - apila tus estilos de nombre, ten una rotación de skins.\n- Ocultar oro es un interruptor sí/no.\n\n<color=#FFD94D><b>QUIÉN VE QUÉ</b></color>\n\n- <color=#7FE87F>El único cosmético que un jugador SIN el mod puede ver jamás es el estilo de nombre</color> - los nombres con estilo viajan en el mismo campo de nombre que vanilla ya renderiza, y meter estilo en un nombre siempre ha sido posible en el ROUNDS vanilla. Aun así, el brillo y la tipografía son extras del mod que una pantalla vanilla no puede mostrar.\n- Todo lo demás - estelas, colores de jugador, auras, caras, skins de mapa - se renderiza solo para jugadores con el mod. Un rival vanilla ve tu color de cuerpo por defecto, sin estela, sin aura, y un hueco vacío donde iría una pieza de cara personalizada. <color=#8A8A93>El juego omite limpiamente la pieza desconocida: sin crasheo, sin sustituto.</color>\n- Los espectadores con mod pueden desactivar individualmente las estelas, los colores de jugador y los cosméticos animados de otros en Ajustes.\n\n<color=#FFD94D><b>STOCK, DROPS Y ADELANTOS</b></color>\n\n- La tienda lista todo por precio y muestra lo que posees, el artista de cada pieza y el stock.\n- Los objetos de la comunidad pueden ser limitados: un drop muestra quedan N de M y se apaga al agotarse.\n- Un objeto puede existir antes de abrirse su venta - aparece como no a la venta hasta que el artista abre las ventas, y las novedades se adelantan primero en el panel de cosméticos nuevos de la pestaña Home. <color=#FF6666>Ver un objeto en Home no significa que ya puedas comprarlo.</color>\n- No puedes comprar un objeto dos veces, y una compra que no puedes pagar se rechaza - sin deudas, sin compras parciales.\n\n<color=#FFD94D><b>EL ESTUDIO DE ARTISTA</b></color>\n\nLos artistas de la comunidad hacen buena parte del catálogo. El circuito:\n\n- Un artista (un rol otorgado en el juego) envía arte desde la pestaña Artista: un PNG de 512x512, un GIF, o hasta 16 fotogramas PNG numerados, posicionados sobre una vista previa en vivo del cuerpo con hueco, escala y desplazamiento.\n- El envío pasa a revisión. La aprobación por sí sola no lo pone a la venta: el arte tiene que salir dentro de una versión del mod primero, porque los cosméticos van empaquetados en el mod para que el juego de cada jugador pueda renderizarlos.\n- Una vez publicado, el artista abre las ventas y controla el precio, el tope de stock y quién puede comprar - un artista puede vetar a jugadores concretos de comprar sus piezas.\n- El artista gana <color=#7FE87F>un 30% de comisión</color> (redondeada hacia abajo a oro entero) cuando otro jugador compra su pieza. Sin comisión en los regalos.\n\n<color=#FFD94D><b>REGALOS</b></color>\n\nSolo los artistas pueden regalar, y solo sus propias piezas: una copia gratis a cualquier jugador que haya usado el mod, incluso antes de abrirse las ventas. Los regalos consumen stock en un drop limitado. No hay regalos entre jugadores, ni forma de enviar oro a otro jugador.')
  ,  ('7d2c24d463786026', 'ru', '19329ffd6e3b0670e93678c0dfd1bde7861598fa', E'Косметика живёт на вкладке Магазин меню F5 и покупается за золото, заработанное игрой. Эта страница - про каждый её вид, как каждый надевается, как работают дропы и запас и откуда берётся арт.\n\n<color=#FFD94D><b>ЧТО ДЕЛАЕТ КАЖДЫЙ ВИД</b></color>\n\n<color=#7FD4FF>Титулы</color> - подпись рядом с твоим именем на поверхностях мода (см. <color=#7FD4FF>Титулы</color>).\n<color=#7FD4FF>Шлейфы</color> - цветной след за твоим телом в матчах. Длина растёт с ценой: шлейфы за 3,000 золота короткие, за 5,000 - средние, за 10,000 - длинные.\n<color=#7FD4FF>Скины карт</color> - перекрашивают всю карту и фон. Надевай сколько хочешь и переключай их посреди игры левым Shift. В каталоге - перекраски в духе шести ванильных артов, больше тридцати оригинальных пресетов, включая ночной пак, и три премиум-скина с блёстками: Gilded, Platinum и Aurora. <color=#7FE87F>Скины карт - только твои</color>: другим игрокам они никогда не отправляются, каждый видит свой собственный выбор.\n<color=#7FD4FF>Стили имени</color> - стакающееся оформление отображаемого имени. Форматирование (жирный, курсив, подчёркивание, зачёркивание, парение) стакается свободно; свечение, размер, трансформация шрифта и гарнитура - по одному, а цветовые эффекты (сплошные, неоновые, радуга, побуквенные градиенты) делят один слот.\n<color=#7FD4FF>Цвета игрока</color> - заменяют твой командный оранжевый или синий собственным цветом и становятся твоей командной идентичностью на экранах с модом (см. <color=#7FD4FF>Цвета команд и тела</color>).\n<color=#7FD4FF>Цвета курсора</color> - перекрашивают курсор мыши. ФОРМА курсора (стандарт, стрелка, точка, прицел, круг) - бесплатная настройка. Твой курсор не видит никто и никогда.\n<color=#7FD4FF>Эффекты игрока</color> - аура из частиц, следующая за твоим телом в матчах.\n<color=#7FD4FF>Лица</color> - кастомные глаза, рты и аксессуары, которые встают в собственный редактор персонажа ROUNDS рядом с ванильными частями и рендерятся везде, где рендерится лицо. Некоторые анимированы; настройка «Анимация косметики» при желании прибивает их к статичному кадру.\n<color=#7FD4FF>Скрыть золото</color> - утилитарный переключатель, маскирующий твоё золото на поверхностях таблиц лидеров.\n\n<color=#FFD94D><b>НАДЕВАНИЕ</b></color>\n\n- По одному: титулы, шлейфы, цвета игрока, цвета курсора и эффекты игрока используют <color=#7FD4FF>Включить</color> / <color=#7FD4FF>Снять</color>.\n- Мульти: стили имени и скины карт используют <color=#7FD4FF>Надеть</color> / <color=#7FD4FF>Убрать</color> - стакай стили имени, держи ротацию скинов.\n- Скрыть золото - переключатель вкл/выкл.\n\n<color=#FFD94D><b>КТО ЧТО ВИДИТ</b></color>\n\n- <color=#7FE87F>Единственная косметика, которую вообще может увидеть игрок БЕЗ мода, - оформление имени</color>: стилизованные имена едут тем же полем имени, которое ваниль и так рендерит, а класть оформление в имя можно было в ванильном ROUNDS всегда. Даже там свечение и гарнитура - надстройки мода, которые ванильный экран не покажет.\n- Всё остальное - шлейфы, цвета игрока, ауры, лица, скины карт - рендерится только игрокам с модом. Ванильный соперник видит твой стандартный цвет тела, без шлейфа, без ауры и пустой слот там, где была бы кастомная часть лица. <color=#8A8A93>Игра чисто пропускает неизвестную часть: без краша и без подмены.</color>\n- Зрители с модом могут по отдельности выключить чужие шлейфы, цвета игрока и анимацию косметики в настройках.\n\n<color=#FFD94D><b>ЗАПАС, ДРОПЫ И АНОНСЫ</b></color>\n\n- Магазин перечисляет всё по цене и показывает, чем ты владеешь, художника каждого предмета и запас.\n- Предметы сообщества бывают ограниченными: дроп показывает «осталось N из M» и сереет, когда распродан.\n- Предмет может существовать до открытия продаж - он висит как «не продаётся», пока художник не откроет продажи, а совсем новые прибытия сначала анонсируются на панели новинок вкладки Главная. <color=#FF6666>Увидеть предмет на Главной не значит, что его уже можно купить.</color>\n- Один предмет дважды не купить, а покупка не по карману отклоняется - без долгов и частичных покупок.\n\n<color=#FFD94D><b>МАСТЕРСКАЯ ХУДОЖНИКА</b></color>\n\nХудожники сообщества делают большую долю каталога. Пайплайн:\n\n- Художник (роль, выдаваемая в игре) отправляет арт со вкладки Художник: PNG 512x512, GIF или до 16 пронумерованных PNG-кадров, размещённые на живом превью тела, со слотом, масштабом и смещением.\n- Заявка уходит на ревью. Одно одобрение ещё не выставляет её на продажу: арт сперва должен выйти внутри релиза мода, потому что косметика вшивается в мод, чтобы игра каждого могла её отрендерить.\n- После выхода художник открывает продажи и управляет ценой, потолком запаса и кругом покупателей - художник может запретить конкретным игрокам покупать свои предметы.\n- Художник получает <color=#7FE87F>роялти 30%</color> (округляется вниз до целого золота), когда его предмет покупает другой игрок. С подарков роялти нет.\n\n<color=#FFD94D><b>ПОДАРКИ</b></color>\n\nДарить могут только художники и только свои предметы: бесплатная копия любому игроку, запускавшему мод, в том числе до открытия продаж. Подарки всё равно тратят запас ограниченного дропа. Дарения между игроками нет, как и способа переслать золото другому игроку.')
  ,  ('7d2c24d463786026', 'uk', '19329ffd6e3b0670e93678c0dfd1bde7861598fa', E'Косметика живе у вкладці «Магазин» меню F5 і купується за золото, зароблене грою. Ця сторінка охоплює всі види, як кожен вдягається, як працюють дропи та запас і звідки береться арт.\n\n<color=#FFD94D><b>ЩО РОБИТЬ КОЖЕН ВИД</b></color>\n\n<color=#7FD4FF>Титули</color> - підпис біля вашого імені на поверхнях мода (див. <color=#7FD4FF>Титули</color>).\n<color=#7FD4FF>Шлейфи</color> - кольоровий шлейф за вашим тілом у матчах. Довжина залежить від ціни: шлейфи за 3,000 золота короткі, за 5,000 середні, за 10,000 довгі.\n<color=#7FD4FF>Скіни мап</color> - перефарбовують усю мапу й тло. Вдягайте скільки завгодно й перемикайте посеред гри лівим Shift. У каталозі перефарбування в стилі шести ванільних артів, понад тридцять оригінальних пресетів, включно з нічним паком, і три преміальні блискучі скіни: Позолота, Платина й Аврора. <color=#7FE87F>Скіни мап - лише ваші</color> - вони ніколи не надсилаються іншим гравцям, тож кожен бачить власний вибір.\n<color=#7FD4FF>Стилі імені</color> - стековане оформлення вашого видимого імені. Форматування (жирний, курсив, підкреслення, закреслення, плавання) стакається вільно; сяйво, розмір, трансформація шрифту й гарнітура - по одному кожного, а колірні ефекти (суцільні, неонові, райдуга, політерні градієнти) ділять один слот.\n<color=#7FD4FF>Кольори гравця</color> - заміняють ваш командний оранжевий чи синій на власний колір і стають вашою командною ідентичністю на екранах із модом (див. <color=#7FD4FF>Кольори команд і тіла</color>).\n<color=#7FD4FF>Кольори курсора</color> - перефарбовують ваш курсор миші. ФОРМА курсора (стандартна, стрілка, крапка, приціл, коло) - безплатне налаштування. Ваш курсор більше не бачить ніхто.\n<color=#7FD4FF>Ефекти гравця</color> - аура з часток, що летить за вашим тілом у матчах.\n<color=#7FD4FF>Обличчя</color> - кастомні очі, роти й аксесуари, що стають у власний редактор персонажа ROUNDS поруч із ванільними частинами й рендеряться всюди, де рендериться обличчя. Деякі анімовані; налаштування «Анімована косметика» за бажанням фіксує їх на нерухомому кадрі.\n<color=#7FD4FF>Сховати золото</color> - службовий перемикач, що маскує ваше золото на таблицях лідерів.\n\n<color=#FFD94D><b>ВДЯГАННЯ</b></color>\n\n- По одному: титули, шлейфи, кольори гравця, кольори курсора та ефекти гравця використовують <color=#7FD4FF>Зробити активним</color> / <color=#7FD4FF>Зняти</color>.\n- Кілька одразу: стилі імені та скіни мап використовують <color=#7FD4FF>Вдягнути</color> / <color=#7FD4FF>Прибрати</color> - стакайте стилі імені, тримайте ротацію скінів.\n- «Сховати золото» - перемикач увімк/вимк.\n\n<color=#FFD94D><b>ХТО ЩО БАЧИТЬ</b></color>\n\n- <color=#7FE87F>Єдина косметика, яку гравець БЕЗ мода взагалі може побачити, - стилі імені</color> - стилізовані імена їдуть тим самим полем імені, яке ваніла й так рендерить, а вписувати стилі в ім''я у ванільному ROUNDS можна було завжди. Та навіть тут сяйво й гарнітура - додатки з боку мода, які ванільний екран показати не може.\n- Усе решта - шлейфи, кольори гравця, аури, обличчя, скіни мап - рендериться лише гравцям із модом. Суперник на ванілі бачить ваш стандартний колір тіла, без шлейфа, без аури, і порожній слот там, де була б кастомна частина обличчя. <color=#8A8A93>Гра чисто пропускає невідому частину: без крашу, без підміни.</color>\n- Глядачі з модом можуть окремо вимкнути чужі шлейфи, кольори гравців і анімовану косметику в Налаштуваннях.\n\n<color=#FFD94D><b>ЗАПАС, ДРОПИ Й ТИЗЕРИ</b></color>\n\n- Магазин перелічує все за ціною й показує, чим ви володієте, художника кожного предмета та запас.\n- Предмети від спільноти бувають лімітованими: дроп показує «лишилося N з M» і сіріє після розпродажу.\n- Предмет може існувати до відкриття продажу - він показується як «не продається», доки художник не відкриє продаж, а новинки спершу тизеряться на панелі найновішої косметики вкладки «Головна». <color=#FF6666>Побачити предмет на Головній ще не означає, що його вже можна купити.</color>\n- Двічі один предмет не купиш, а покупка не по кишені відхиляється - без боргів і часткових покупок.\n\n<color=#FFD94D><b>СТУДІЯ ХУДОЖНИКА</b></color>\n\nХудожники спільноти створюють велику частку каталогу. Конвеєр:\n\n- Художник (роль, що видається у грі) подає арт із вкладки «Художник»: PNG 512x512, GIF або до 16 пронумерованих PNG-кадрів, розміщені на живому передперегляді на тілі зі слотом, масштабом і зсувом.\n- Подання йде на перевірку. Саме схвалення ще не виставляє його на продаж: арт спершу має вийти всередині релізу мода, бо косметика вшивається в мод, щоб гра кожного гравця могла її рендерити.\n- Після виходу художник відкриває продаж і керує ціною, лімітом запасу й тим, хто може купувати - художник може заборонити купівлю своїх предметів конкретним гравцям.\n- Художник заробляє <color=#7FE87F>роялті 30%</color> (округлені вниз до цілого золота), коли його предмет купує інший гравець. За подарунки роялті немає.\n\n<color=#FFD94D><b>ПОДАРУНКИ</b></color>\n\nДарувати можуть лише художники й лише власні предмети: безплатна копія будь-якому гравцю, що користувався модом, навіть до відкриття продажу. Подарунки все одно витрачають запас лімітованого дропу. Дарування між гравцями немає, як і способу переслати золото іншому гравцю.')
  ,  ('7d2c24d463786026', 'sv', '19329ffd6e3b0670e93678c0dfd1bde7861598fa', E'Kosmetik finns på F5-menyns Butik-flik och köps med guldet du tjänar genom att spela. Den här sidan täcker varje sort, hur var och en utrustas, hur släpp och lager fungerar, och varifrån konsten kommer.\n\n<color=#FFD94D><b>VAD VARJE SORT GÖR</b></color>\n\n<color=#7FD4FF>Titlar</color> - etiketten bredvid ditt namn på moddens ytor (se <color=#7FD4FF>Titlar</color>).\n<color=#7FD4FF>Spår</color> - ett färgat spår bakom din kropp i matcher. Längden skalar med priset: spår för 3 000 guld är korta, 5 000 medellånga, 10 000 långa.\n<color=#7FD4FF>Kartskins</color> - färgar om hela kartan och bakgrunden. Utrusta hur många du vill och växla mellan dem mitt i matchen med vänster Shift. Katalogen rymmer omfärgningar i stil med de sex originalarterna, över trettio egna förinställningar inklusive nattpaketet, och tre premium-gnistskins: Gilded, Platinum och Aurora. <color=#7FE87F>Kartskins är dina helt privat</color> - de skickas aldrig till andra spelare, så varje spelare ser sitt eget val.\n<color=#7FD4FF>Namnstilar</color> - stapelbar styling på ditt visningsnamn. Formatering (fet, kursiv, understrykning, genomstrykning, svävning) staplas fritt; glöd, storlek, teckentransform och typsnitt tillåter en var, och färgeffekterna (solida, neon, regnbåge, gradienter per bokstav) delar en plats.\n<color=#7FD4FF>Spelarfärger</color> - ersätt ditt lags orange eller blått med en egen färg, och bli din lagidentitet på moddade skärmar (se <color=#7FD4FF>Lag- & kroppsfärger</color>).\n<color=#7FD4FF>Pekarfärger</color> - färga om din muspekare. Pekarens FORM (standard, pil, punkt, hårkors, cirkel) är en gratis preferens. Ingen annan ser någonsin din pekare.\n<color=#7FD4FF>Spelareffekter</color> - en partikelaura som följer din kropp i matcher.\n<color=#7FD4FF>Ansikten</color> - egna ögon, munnar och accessoarer som får plats i ROUNDS egen karaktärseditor bredvid originaldelarna, och renderas överallt där ett ansikte renderas. Vissa är animerade; inställningen Animerad kosmetik låser dem till en stillbild om du föredrar det.\n<color=#7FD4FF>Dölj guld</color> - en praktisk växel som maskerar ditt guld på topplistytor.\n\n<color=#FFD94D><b>UTRUSTNING</b></color>\n\n- En i taget: titlar, spår, spelarfärger, pekarfärger och spelareffekter använder <color=#7FD4FF>Aktivera</color> / <color=#7FD4FF>Ta av</color>.\n- Flera samtidigt: namnstilar och kartskins använder <color=#7FD4FF>Utrusta</color> / <color=#7FD4FF>Ta bort</color> - stapla dina namnstilar, håll en rotation av skins.\n- Dölj guld är en på/av-växel.\n\n<color=#FFD94D><b>VEM SER VAD</b></color>\n\n- <color=#7FE87F>Den enda kosmetik en spelare UTAN modden någonsin kan se är namnstyling</color> - stilade namn åker med i samma namnfält originalet redan renderar, och att lägga styling i ett namn har alltid varit möjligt i original-ROUNDS. Även där är glöd och typsnitt modd-extras som en originalskärm inte kan visa.\n- Allt annat - spår, spelarfärger, auror, ansikten, kartskins - renderas bara för spelare med modden. En motståndare utan modden ser din standardkroppsfärg, inget spår, ingen aura och en tom plats där en egen ansiktsdel skulle sitta. <color=#8A8A93>Spelet hoppar snyggt över den okända delen: ingen krasch, inget som ersätter.</color>\n- Moddade tittare kan var för sig stänga av andra spelares spår, spelarfärger och animerade kosmetik i Inställningar.\n\n<color=#FFD94D><b>LAGER, SLÄPP OCH TEASERS</b></color>\n\n- Butiken listar allt efter pris och visar vad du äger, varje föremåls konstnär och lagret.\n- Communityföremål kan vara begränsade: ett släpp visar N av M kvar och gråtonas när det är slutsålt.\n- Ett föremål kan finnas innan försäljningen öppnar - det visas som ej till salu tills konstnären öppnar försäljningen, och helt nya tillskott teasas först på Hem-flikens panel för nyaste kosmetik. <color=#FF6666>Att se ett föremål på Hem betyder inte att du kan köpa det än.</color>\n- Du kan inte köpa ett föremål två gånger, och ett köp du inte har råd med nekas - ingen skuld, inga delköp.\n\n<color=#FFD94D><b>KONSTNÄRSSTUDION</b></color>\n\nCommunityns konstnärer står för en stor del av katalogen. Pipelinen:\n\n- En konstnär (en roll som ges i spelet) skickar in konst från Konstnärsfliken: en 512x512-PNG, en GIF eller upp till 16 numrerade PNG-bildrutor, positionerade i en live-förhandsvisning på kroppen med plats, skala och offset.\n- Bidraget går till granskning. Ett godkännande ensamt sätter det inte till salu: konsten måste först skeppas i en modversion, eftersom kosmetik buntas in i modden så att varje spelares spel kan rendera den.\n- När den skeppats öppnar konstnären försäljningen och styr priset, lagertaket och vem som får köpa - en konstnär kan blockera specifika spelare från att köpa sina föremål.\n- Konstnären tjänar <color=#7FE87F>30% i royalty</color> (avrundat nedåt till helt guld) när en annan spelare köper deras föremål. Ingen royalty på gåvor.\n\n<color=#FFD94D><b>GÅVOR</b></color>\n\nBara konstnärer kan ge bort, och bara sina egna föremål: en gratis kopia till valfri spelare som har använt modden, även innan försäljningen öppnat. Gåvor drar ändå från lagret på ett begränsat släpp. Det finns ingen gåvogivning spelare till spelare, och inget sätt att skicka guld till en annan spelare.');

INSERT INTO i18n_proposals
  (key_id, language_code, source_hash, proposed_target, proposer_steam_id,
   license_assent, license_terms_rev, assented_at, status, created_at)
SELECT v.key_id, v.lang, v.source_hash, v.target, 'claude-mt',
       TRUE, 'machine-v1', NOW(), 'pending', NOW()
  FROM _seed341 v
  JOIN i18n_keys k ON k.key_id = v.key_id AND k.retired_at IS NULL
                  AND k.source_hash = v.source_hash
 WHERE NOT EXISTS (
   SELECT 1 FROM i18n_proposals p
    WHERE p.key_id = v.key_id AND p.language_code = v.lang
      AND p.status = 'pending')
   AND NOT EXISTS (
   SELECT 1 FROM i18n_proposals p2
    WHERE p2.key_id = v.key_id AND p2.language_code = v.lang
      AND p2.proposer_steam_id = 'claude-mt'
      AND p2.source_hash = v.source_hash);

DO $$
DECLARE
  uncovered INTEGER;
  sample TEXT;
BEGIN
  SELECT COUNT(*) INTO uncovered
    FROM _seed341 v
   WHERE NOT EXISTS (
           SELECT 1 FROM i18n_proposals p
            WHERE p.key_id = v.key_id AND p.language_code = v.lang
              AND (p.source_hash = v.source_hash OR p.status = 'pending'))
     AND NOT EXISTS (
           SELECT 1 FROM i18n_entries e
            WHERE e.key_id = v.key_id AND e.language_code = v.lang
              AND e.state = 'approved');
  IF uncovered <> 0 THEN
    SELECT string_agg(x.key_id || '/' || x.lang, ', ')
      INTO sample
      FROM (SELECT v.key_id, v.lang FROM _seed341 v
             WHERE NOT EXISTS (
                     SELECT 1 FROM i18n_proposals p
                      WHERE p.key_id = v.key_id AND p.language_code = v.lang
                        AND (p.source_hash = v.source_hash OR p.status = 'pending'))
               AND NOT EXISTS (
                     SELECT 1 FROM i18n_entries e
                      WHERE e.key_id = v.key_id AND e.language_code = v.lang
                        AND e.state = 'approved')
             LIMIT 5) x;
    RAISE EXCEPTION 'migration 341: % of 12 seed pairs did not land (e.g. %) - the usual cause is that 340 / tools/i18n_sync_keys.py has not run against this database yet; nothing committed', uncovered, sample;
  END IF;

  RAISE NOTICE 'migration 341: all 12 seed pairs covered (3 keys x es/ru/uk/sv)';
END $$;

COMMIT;
